"use client";

import { useState } from "react";
import {
  type ExpanderState,
  expanderDevice,
} from "@/components/audio-ui/devices/expander/device";
import { createExpanderEngine } from "@/components/audio-ui/devices/expander/engine";
import { ExpanderPanel } from "@/components/audio-ui/devices/expander/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";

const MASTER_VOLUME = 0.7;

/**
 * An expander you can plug in: its state, a panel that draws its curve and
 * an engine that plays it, each its own file and none knowing the others. Play
 * the loop: downward, what falls under the threshold is turned down; upward,
 * the peaks are lifted.
 */
export function BlockExpander() {
  const [state, setState] = useState<ExpanderState>(() =>
    expanderDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  useDeviceLoop({
    create: createExpanderEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-none h-full w-full min-w-0">
      <ExpanderPanel onValueChange={setState} value={state} />
    </div>
  );
}
